buggy.simple_imputer_constant_fillvalue_cast:
import numpy as np
from sklearn.impute import SimpleImputer


def raises_value_error(fn):
    try:
        fn()
    except ValueError:
        return 1.0
    except Exception:
        return 0.5
    return 0.0


X_int = np.array([0, 0, 0, 1]).reshape(-1, 1)

probe("float_fill_into_int_raises", raises_value_error(
    lambda: SimpleImputer(missing_values=0, fill_value=3.2, strategy="constant").fit_transform(X_int)))

probe("nan_fill_into_int_raises", raises_value_error(
    lambda: SimpleImputer(missing_values=0, fill_value=np.nan, strategy="constant").fit_transform(X_int)))

probe("float_fill_fit_int64_raises", raises_value_error(
    lambda: SimpleImputer(strategy="constant", fill_value=1.5, missing_values=2).fit(
        np.array([[1, 2, 3], [2, 3, 4]], dtype=np.int64))))

X_f32 = np.array([[1.0, 2.0], [3.0, 4.0]], dtype=np.float32)


def same_kind_preserved():
    try:
        out = SimpleImputer(strategy="constant", fill_value=np.float64(1.5), missing_values=2).fit_transform(X_f32)
        return 1.0 if out.dtype == np.float32 else 0.0
    except ValueError:
        return -1.0


probe("samekind_float32_preserved", same_kind_preserved())

